from types import SimpleNamespace
from click._termui_impl import ProgressBar

for pct in (0, 0.375, 0.999, 1):
    bar = SimpleNamespace(pct=pct)
    assert ProgressBar.format_pct(bar) == f"{int(pct * 100): 4}%"[1:]
    assert ProgressBar.format_pct(bar, decimals=0) == f"{int(pct * 100): 4}%"[1:]
    for decimals in (1, 2, 4):
        assert ProgressBar.format_pct(bar, decimals=decimals) == f"{pct * 100:.{decimals}f}%"
assert ProgressBar.format_pct(SimpleNamespace(pct=0.375), decimals=1) == '37.5%'
try:
    ProgressBar.format_pct(SimpleNamespace(pct=0), decimals=-1)
except ValueError:
    pass
else:
    raise AssertionError('negative decimals accepted')
try:
    ProgressBar.format_pct(SimpleNamespace(pct=0), 1)
except TypeError:
    pass
else:
    raise AssertionError('positional decimals accepted')
print('Focused checks passed')
'@ | python -B -; if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }; git diff --check; git status --short; git --no-pager diff --stat

